const text = $json.inquiry || '';
const lower = text.toLowerCase();
const language = /\b(hallo|ich|suche|wohnung|haus)\b/i.test(text) ? 'German' : /\b(hola|busco|presupuesto|piso|casa|habitaciones)\b/i.test(text) ? 'Spanish' : 'English';
function parseBudget(s) {
  const m = s.match(/(?:€|eur\s*)?([0-9]+(?:[.,][0-9]+)?)\s*(m|million|k)?/i);
  if (!m) return null;
  const suffix = (m[2] || '').toLowerCase();
  const token = m[1];
  let n;
  if (suffix === 'm' || suffix === 'million') n = Number(token.replace(',', '.')) * 1000000;
  else if (suffix === 'k') n = Number(token.replace(',', '.')) * 1000;
  else n = Number(token.replace(/[.,](?=\d{3}\b)/g, '').replace(',', '.'));
  if (!Number.isFinite(n) || n < 100000) return null;
  return Math.round(n);
}
const euroMatch = text.match(/(?:€\s*[0-9][0-9.,]*\s*(?:m|k)?|[0-9][0-9.,]*\s*(?:million|m|k)\s*(?:euros?|eur)?)/i);
const budget = euroMatch ? parseBudget(euroMatch[0]) : null;
const areas = ['Palma','Sóller','Artà','Sant Llorenç des Cardassar','Cala d\'Or','Inca'];
const location = areas.find(a => lower.includes(a.toLowerCase())) || null;
const types = ['apartment','townhouse','villa','finca'];
const aliases = { apartment: ['apartment','flat','piso','wohnung'], townhouse: ['townhouse','casa de pueblo','stadthaus','house'], villa: ['villa'], finca: ['finca','country house','landhaus'] };
const propertyType = types.find(t => aliases[t].some(a => lower.includes(a))) || null;
const bedroomMatch = lower.match(/(\d+)[\s-]*(?:bed|bedroom|habitaci|schlafzimmer)/);
const bedrooms = bedroomMatch ? Number(bedroomMatch[1]) : null;
const timeline = /three months|3 months|tres meses|drei monaten/.test(lower) ? 'Within 3 months' : /six months|6 months|seis meses|sechs monaten/.test(lower) ? 'Within 6 months' : null;
const financing = /finance|mortgage|hipoteca|finanzier/.test(lower) ? 'Financing mentioned' : null;
const purpose = /invest|rental|rent|inversi|anlage/.test(lower) ? 'Investment' : /home|live|vivir|wohnen/.test(lower) ? 'Own use' : null;
const fields = { budget, location, propertyType, bedrooms, timeline, financing, purpose };
const weights = { budget: 25, location: 20, propertyType: 15, bedrooms: 15, timeline: 15, financing: 10 };
let score = 0;
for (const [key, weight] of Object.entries(weights)) if (fields[key] !== null) score += weight;
const priority = score >= 70 ? 'Hot' : score >= 45 ? 'Warm' : 'Cold';
const missing = Object.entries(fields).filter(([k,v]) => v === null && ['budget','location','propertyType','bedrooms','timeline'].includes(k)).map(([k]) => k);
return [{ json: { inquiry: text, language, ...fields, score, priority, missing } }];

const lead = $json;
const properties = [
 {id:'PM-101',title:'Palma Old Town Apartment',location:'Palma',type:'apartment',price:575000,bedrooms:2,features:['renovated','balcony','central']},
 {id:'PM-102',title:'Santa Catalina Townhouse',location:'Palma',type:'townhouse',price:895000,bedrooms:3,features:['terrace','character property','central']},
 {id:'PM-103',title:'Port de Sóller Sea View Apartment',location:'Sóller',type:'apartment',price:760000,bedrooms:2,features:['sea view','terrace','lift']},
 {id:'PM-104',title:'Artà Stone Finca',location:'Artà',type:'finca',price:1390000,bedrooms:4,features:['tourist licence','pool','solar energy']},
 {id:'PM-105',title:'Sant Llorenç Townhouse',location:'Sant Llorenç des Cardassar',type:'townhouse',price:435000,bedrooms:2,features:['pool','terrace','licence']},
 {id:'PM-106',title:"Cala d'Or Frontline Apartment",location:"Cala d'Or",type:'apartment',price:290000,bedrooms:2,features:['sea front','renovation opportunity']},
 {id:'PM-107',title:'Palma Family Villa',location:'Palma',type:'villa',price:1250000,bedrooms:4,features:['pool','parking','garden']},
 {id:'PM-108',title:'Inca Renovation House',location:'Inca',type:'townhouse',price:320000,bedrooms:3,features:['renovation','patio','investment potential']}
];
const needsLicence = /tourist|holiday rental|licen[cs]e|licencia|ferienvermiet/.test(lead.inquiry.toLowerCase());
const matches = properties.filter(p =>
  (!lead.budget || p.price <= lead.budget) &&
  (!lead.location || p.location.toLowerCase().includes(lead.location.toLowerCase())) &&
  (!lead.propertyType || p.type === lead.propertyType) &&
  (!lead.bedrooms || p.bedrooms >= lead.bedrooms) &&
  (!needsLicence || p.features.some(f => f.includes('licence')))
).map(p => ({...p, matchReason: 'Compatible with the stated budget and core requirements'})).slice(0,3);
const humanReview = lead.missing.includes('budget') || lead.missing.includes('location') || matches.length === 0;
return [{ json: { ...lead, matches, humanReview } }];

const lead = $json;
const missingText = lead.missing.length ? ` Missing information: ${lead.missing.join(', ')}.` : '';
const matchText = lead.matches.length ? ` Suggested properties: ${lead.matches.map(p => p.id + ' ' + p.title).join('; ')}.` : ' No compatible property was found.';
const opening = lead.language === 'German' ? 'Vielen Dank für Ihre Anfrage.' : lead.language === 'Spanish' ? 'Gracias por su consulta.' : 'Thank you for your enquiry.';
const draftReply = `${opening}${missingText}${matchText} An agent will review this information before replying.`;
return [{ json: { leadSummary: { language: lead.language, budget: lead.budget, location: lead.location, propertyType: lead.propertyType, bedrooms: lead.bedrooms, timeline: lead.timeline }, score: lead.score, priority: lead.priority, missing: lead.missing, matches: lead.matches, humanReview: true, draftReply, status: 'Awaiting agent approval' } }];
